me back clean (run-0003) and simulation passed under Icarus (run-0004). These runs are not evidence, and none of them can be listed in tool_runs.", "I have not run synthesis with Yosys. The design is written to have no latches: every combinational variable gets a default value and the case statement has a default branch.", "I have not run the testbench under Verilator, although section 7 of the interface spec asks for both Icarus and Verilator."], "escalation": null, "notes": "Decisions I made: no formal_spec file is submitted, because the expected outputs are rtl_source and testbench only. The formal proof required by the interface spec, the separate sync_fifo_tb_fail.v failure-path testbench and the DEPTH 5 proof are still open for a later task. Reset during traffic is counted as covered when reset arrives while the FIFO holds entries. The storage is not reset, as the microarchitecture says."}

=== FILE: sync_fifo.v ===
// sync_fifo: parameterizable synchronous FIFO, first-word fall-through.
// Implements microarchitecture.md: explicit occupancy counter, pointers
// wrapping at LAST = DEPTH-1, flags compared on the count register.
module sync_fifo #(
    parameter integer DEPTH = 8,
    parameter integer WIDTH = 8
) (
    input  wire                       clk,
    input  wire                       rst_n,
    input  wire                       wr_en,
    input  wire [WIDTH-1:0]           wr_data,
    output wire                       full,
    input  wire                       rd_en,
    output wire [WIDTH-1:0]           rd_data,
    output wire                       empty,
    output wire [$clog2(DEPTH+1)-1:0] count
);

  localparam integer AW     = (DEPTH > 1) ? $clog2(DEPTH) : 1;
  localparam integer CW     = $clog2(DEPTH + 1);
  localparam integer LAST_I = DEPTH - 1;
  localparam [AW-1:0] LAST    = LAST_I[AW-1:0];
  localparam [AW-1:0] PTR_ONE = 1;
  localparam [CW-1:0] CNT_ONE = 1;
  localparam [CW-1:0] CNT_MAX = DEPTH[CW-1:0];

  reg [WIDTH-1:0] mem [0:DEPTH-1];

  reg [AW-1:0] wr_ptr;
  reg [AW-1:0] rd_ptr;
  reg [CW-1:0] count_q;
  reg [AW-1:0] wr_ptr_d;
  reg [AW-1:0] rd_ptr_d;
  reg [CW-1:0] count_d;

  wire wr_acc;
  wire rd_acc;

  assign full    = (count_q == CNT_MAX);
  assign empty   = (count_q == {CW{1'b0}});
  assign count   = count_q;
  assign wr_acc  = wr_en && !full;
  assign rd_acc  = rd_en && !empty;
  assign rd_data = mem[rd_ptr];

  // Next-state logic.
  always @* begin
    wr_ptr_d = wr_ptr;
    rd_ptr_d = rd_ptr;
    count_d  = count_q;
    if (wr_acc) begin
      wr_ptr_d = (wr_ptr == LAST) ? {AW{1'b0}} : (wr_ptr + PTR_ONE);
    end
    if (rd_acc) begin
      rd_ptr_d = (rd_ptr == LAST) ? {AW{1'b0}} : (rd_ptr + PTR_ONE);
    end
    case ({wr_acc, rd_acc})
      2'b10:   count_d = count_q + CNT_ONE;
      2'b01:   count_d = count_q - CNT_ONE;
      default: count_d = count_q;
    endcase
  end

  // Control registers: synchronous, active-low reset.
  always @(posedge clk) begin
    if (!rst_n) begin
      wr_ptr  <= {AW{1'b0}};
      rd_ptr  <= {AW{1'b0}};
      count_q <= {CW{1'b0}};
    end else begin
      wr_ptr  <= wr_ptr_d;
      rd_ptr  <= rd_ptr_d;
      count_q <= count_d;
    end
  end

  // Storage: datapath, not reset, written only outside reset.
  always @(posedge clk) begin
    if (rst_n && wr_acc) begin
      mem[wr_ptr] <= wr_data;
    end
  end

endmodule
=== END FILE ===
=== FILE: sync_fifo_tb.v ===
`timescale 1ns/1ps
// Self-checking testbench for sync_fifo: two DUTs (DEPTH 8 x WIDTH 8 and
// DEPTH 5 x WIDTH 12) on the same stimulus, each checked every cycle
// against a reference queue. Coverage counters fail the run if a corner
// case from interface_spec.md section 7 was not reached.
module sync_fifo_tb;
  reg clk = 1'b0;
  always #5 clk = ~clk;

  reg        rst_n;
  reg        wr_en;
  reg        rd_en;
  reg [7:0]  wd8;
  reg [11:0] wd12;

  wire       full8, empty8;
  wire [3:0] count8;
  wire [7:0] rd8;
  wire       full5, empty5;
  wire [2:0] count5;
  wire [11:0] rd5;

  sync_fifo #(.DEPTH(8), .WIDTH(8)) u8 (
    .clk(clk), .rst_n(rst_n), .wr_en(wr_en), .wr_data(wd8), .full(full8),
    .rd_en(rd_en), .rd_data(rd8), .empty(empty8), .count(count8));

  sync_fifo #(.DEPTH(5), .WIDTH(12)) u5 (
    .clk(clk), .rst_n(rst_n), .wr_en(wr_en), .wr_data(wd12), .full(full5),
    .rd_en(rd_en), .rd_data(rd5), .empty(empty5), .count(count5));

  // Reference models.
  reg [7:0]  q8 [0:7];
  reg [11:0] q5 [0:4];
  integer h8, t8, c8, h5, t5, c5;
  integer seen_full8, seen_full5;
  integer cov8 [0:8];
  integer cov5 [0:8];
  integer passed, failed, i, k;
  reg [8*64-1:0] nonce;

  task model_step;
    reg wa, ra;
    begin
      if (!rst_n) begin
        if (c8 > 0) cov8[8] = cov8[8] + 1;
        if (c5 > 0) cov5[8] = cov5[8] + 1;
        h8 = 0; t8 = 0; c8 = 0; seen_full8 = 0;
        h5 = 0; t5 = 0; c5 = 0; seen_full5 = 0;
      end else begin
        // DEPTH 8
        wa = wr_en && (c8 != 8);
        ra = rd_en && (c8 != 0);
        if (wr_en && c8 == 8) cov8[1] = cov8[1] + 1;
        if (rd_en && c8 == 0) cov8[3] = cov8[3] + 1;
        if (wr_en && rd_en) begin
          if (c8 == 0) cov8[4] = cov8[4] + 1;
          else if (c8 == 8) cov8[5] = cov8[5] + 1;
          else cov8[6] = cov8[6] + 1;
        end
        if (ra) begin
          if (h8 == 7) begin cov8[7] = cov8[7] + 1; h8 = 0; end
          else h8 = h8 + 1;
          c8 = c8 - 1;
        end
        if (wa) begin
          q8[t8] = wd8;
          t8 = (t8 == 7) ? 0 : t8 + 1;
          c8 = c8 + 1;
        end
        if (c8 == 8) begin cov8[0] = cov8[0] + 1; seen_full8 = 1; end
        if (c8 == 0 && seen_full8 != 0) begin cov8[2] = cov8[2] + 1; seen_full8 = 0; end
        // DEPTH 5
        wa = wr_en && (c5 != 5);
        ra = rd_en && (c5 != 0);
        if (wr_en && c5 == 5) cov5[1] = cov5[1] + 1;
        if (rd_en && c5 == 0) cov5[3] = cov5[3] + 1;
        if (wr_en && rd_en) begin
          if (c5 == 0) cov5[4] = cov5[4] + 1;
          else if (c5 == 5) cov5[5] = cov5[5] + 1;
          else cov5[6] = cov5[6] + 1;
        end
        if (ra) begin
          if (h5 == 4) begin cov5[7] = cov5[7] + 1; h5 = 0; end
          else h5 = h5 + 1;
          c5 = c5 - 1;
        end
        if (wa) begin
          q5[t5] = wd12;
          t5 = (t5 == 4) ? 0 : t5 + 1;
          c5 = c5 + 1;
        end
        if (c5 == 5) begin cov5[0] = cov5[0] + 1; seen_full5 = 1; end
        if (c5 == 0 && seen_full5 != 0) begin cov5[2] = cov5[2] + 1; seen_full5 = 0; end
      end
    end
  endtask

  task check_one;
    input ok;
    input [8*24-1:0] what;
    begin
      if (ok) passed = passed + 1;
      else begin
        failed = failed + 1;
        $error("t=%0t mismatch: %0s (c8=%0d count8=%0d c5=%0d count5=%0d)",
               $time, what, c8, count8, c5, count5);
      end
    end
  endtask

  task check;
    begin
      check_one(count8 === c8[3:0], "count8");
      check_one(full8 === (c8 == 8), "full8");
      check_one(empty8 === (c8 == 0), "empty8");
      check_one(!(full8 && empty8), "flags8 exclusive");
      if (c8 != 0) check_one(rd8 === q8[h8], "rd_data8");
      check_one(count5 === c5[2:0], "count5");
      check_one(full5 === (c5 == 5), "full5");
      check_one(empty5 === (c5 == 0), "empty5");
      check_one(!(full5 && empty5), "flags5 exclusive");
      if (c5 != 0) check_one(rd5 === q5[h5], "rd_data5");
    end
  endtask

  task do_cycle;
    input r;
    input w;
    input rd;
    begin
      rst_n = r;
      wr_en = w;
      rd_en = rd;
      wd8   = $random;
      wd12  = $random;
      @(posedge clk);
      #1;
      model_step;
      check;
    end
  endtask

  task rand_phase;
    input integer n;
    input integer pw;
    input integer pr;
    begin
      for (k = 0; k < n; k = k + 1)
        do_cycle(1'b1, (({$random} % 100) < pw), (({$random} % 100) < pr));
    end
  endtask

  initial begin
    if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = "none";
    passed = 0; failed = 0;
    h8 = 0; t8 = 0; c8 = 0; h5 = 0; t5 = 0; c5 = 0;
    seen_full8 = 0; seen_full5 = 0;
    for (i = 0; i < 9; i = i + 1) begin cov8[i] = 0; cov5[i] = 0; end
    rst_n = 1'b0; wr_en = 1'b0; rd_en = 1'b0; wd8 = 8'd0; wd12 = 12'd0;

    // Reset, with requests active (they must be ignored).
    repeat (3) do_cycle(1'b0, 1'b1, 1'b1);
    // Read while empty.
    repeat (2) do_cycle(1'b1, 1'b0, 1'b1);
    // Write and read together when empty.
    do_cycle(1'b1, 1'b1, 1'b1);
    // Fill to full, then writes while full.
    repeat (10) do_cycle(1'b1, 1'b1, 1'b0);
    // Write and read together when full, then in between.
    repeat (3) do_cycle(1'b1, 1'b1, 1'b1);
    repeat (3) do_cycle(1'b1, 1'b1, 1'b0);
    // Drain to empty (pointer wrap), then reads while empty.
    repeat (12) do_cycle(1'b1, 1'b0, 1'b1);
    // Random traffic with varying stall rates.
    rand_phase(500, 70, 30);
    rand_phase(500, 30, 70);
    rand_phase(500, 50, 50);
    rand_phase(500, 90, 90);
    // Reset during traffic.
    repeat (4) do_cycle(1'b1, 1'b1, 1'b0);
    repeat (2) do_cycle(1'b0, 1'b1, 1'b1);
    rand_phase(300, 60, 40);
    repeat (3) do_cycle(1'b0, 1'b1, 1'b1);
    rand_phase(300, 50, 60);

    // Coverage goals.
    for (i = 0; i < 9; i = i + 1) begin
      if (cov8[i] == 0) begin failed = failed + 1; $error("coverage goal %0d not reached at DEPTH 8", i); end
      else passed = passed + 1;
      if (cov5[i] == 0) begin failed = failed + 1; $error("coverage goal %0d not reached at DEPTH 5", i); end
      else passed = passed + 1;
    end

    $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
    $finish;
  end
endmodule
=== END FILE ===
